-- BuzzHub Postgres schema, converted from the SQLite schema with every migration applied.
-- Timestamps stay as UTC text (YYYY-MM-DD HH:MM:SS) so the API contract is unchanged.

CREATE TABLE IF NOT EXISTS "area_alerts" (
  "area" TEXT NOT NULL,
  "kind" TEXT NOT NULL,
  "at" TEXT NOT NULL,
  PRIMARY KEY (area, kind)
);

CREATE TABLE IF NOT EXISTS "assets" (
  "key" TEXT PRIMARY KEY,
  "mime" TEXT NOT NULL,
  "data" BYTEA NOT NULL,
  "updated_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "audit" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ts" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "user_id" BIGINT,
  "user_name" TEXT,
  "action" TEXT NOT NULL,
  "detail" TEXT,
  "ip" TEXT
);

CREATE TABLE IF NOT EXISTS "auto_sends" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "customer_id" BIGINT NOT NULL,
  "flow" TEXT NOT NULL,
  "code" TEXT,
  "sent_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "reached" BIGINT NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS "availability" (
  "user_id" BIGINT NOT NULL,
  "dow" BIGINT NOT NULL,
  "available" BIGINT NOT NULL DEFAULT 1,
  "start_time" TEXT,
  "end_time" TEXT,
  PRIMARY KEY (user_id, dow)
);

CREATE TABLE IF NOT EXISTS "bank_deposits" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "source" TEXT NOT NULL CHECK (source IN ('cash','card','app')),
  "amount_cents" BIGINT NOT NULL,
  "deposit_date" TEXT NOT NULL,
  "cover_from" TEXT NOT NULL,
  "cover_to" TEXT NOT NULL,
  "reference" TEXT,
  "note" TEXT,
  "external_id" TEXT UNIQUE,
  "created_by" BIGINT,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "bill_orders" (
  "bill_id" BIGINT NOT NULL,
  "order_id" BIGINT NOT NULL,
  PRIMARY KEY (bill_id, order_id)
);

CREATE TABLE IF NOT EXISTS "bill_payments" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "bill_id" BIGINT NOT NULL,
  "amount_cents" BIGINT NOT NULL,
  "method" TEXT NOT NULL,
  "reference" TEXT,
  "paid_on" TEXT NOT NULL,
  "user_id" BIGINT,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "bills" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "token" TEXT NOT NULL UNIQUE,
  "table_id" BIGINT,
  "status" TEXT NOT NULL DEFAULT 'open',
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "closed_at" TEXT
);

CREATE TABLE IF NOT EXISTS "bookings" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "customer_id" BIGINT NOT NULL,
  "service_id" BIGINT,
  "service_name" TEXT,
  "party_size" BIGINT NOT NULL DEFAULT 1,
  "start_local" TEXT NOT NULL,
  "notes" TEXT,
  "status" TEXT NOT NULL DEFAULT 'booked' CHECK (status IN ('booked','checked_in','done','cancelled','noshow')),
  "guest_id" BIGINT,
  "reminded_at" TEXT,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "deposit_cents" BIGINT NOT NULL DEFAULT 0,
  "deposit_status" TEXT NOT NULL DEFAULT 'none',
  "deposit_pi" TEXT,
  "deposit_code" TEXT,
  "table_id" BIGINT,
  "duration_minutes" BIGINT,
  "late_minutes" BIGINT,
  "late_at" TEXT,
  "preorder" TEXT,
  "preorder_reminded" TEXT,
  "preorder_paid_cents" BIGINT NOT NULL DEFAULT 0,
  "combo_id" BIGINT
);

CREATE TABLE IF NOT EXISTS "campaigns" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "title" TEXT NOT NULL,
  "message" TEXT NOT NULL,
  "audience" TEXT NOT NULL DEFAULT 'all',
  "promo_id" BIGINT,
  "link" TEXT NOT NULL DEFAULT 'order',
  "sent_at" TEXT,
  "pushed" BIGINT NOT NULL DEFAULT 0,
  "emailed" BIGINT NOT NULL DEFAULT 0,
  "reached" BIGINT NOT NULL DEFAULT 0,
  "created_by" BIGINT,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "cash_moves" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "session_id" BIGINT NOT NULL,
  "kind" TEXT NOT NULL CHECK (kind IN ('in','out')),
  "amount_cents" BIGINT NOT NULL,
  "reason" TEXT,
  "user_id" BIGINT,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "cash_sessions" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "opened_by" BIGINT,
  "opened_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "opening_cents" BIGINT NOT NULL,
  "closed_by" BIGINT,
  "closed_at" TEXT,
  "counted_cents" BIGINT,
  "expected_cents" BIGINT,
  "notes" TEXT
);

CREATE TABLE IF NOT EXISTS "catering_feedback" (
  "invoice_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "rating" BIGINT,
  "comment" TEXT,
  "sent_at" TEXT,
  "responded_at" TEXT
);

CREATE TABLE IF NOT EXISTS "catering_packages" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" TEXT NOT NULL,
  "description" TEXT,
  "price_cents" BIGINT NOT NULL,
  "unit" TEXT NOT NULL DEFAULT 'each' CHECK (unit IN ('each','person')),
  "min_qty" BIGINT NOT NULL DEFAULT 1,
  "serves" BIGINT,
  "active" BIGINT NOT NULL DEFAULT 1,
  "sort" BIGINT NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS "certificates" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" BIGINT NOT NULL,
  "kind" TEXT NOT NULL,
  "number" TEXT,
  "issued" TEXT,
  "expires" TEXT,
  "photo_version" TEXT NOT NULL DEFAULT '0',
  "verified_by" BIGINT,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "checklist_runs" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "template_id" BIGINT NOT NULL,
  "day" TEXT NOT NULL,
  "done" TEXT NOT NULL DEFAULT '{}',
  "completed_at" TEXT,
  "completed_by" BIGINT,
  UNIQUE (template_id, day)
);

CREATE TABLE IF NOT EXISTS "checklist_templates" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" TEXT NOT NULL,
  "kind" TEXT NOT NULL DEFAULT 'daily' CHECK (kind IN ('open','close','daily','weekly')),
  "dow" BIGINT,
  "due_time" TEXT,
  "items" TEXT NOT NULL DEFAULT '[]',
  "active" BIGINT NOT NULL DEFAULT 1,
  "sort" BIGINT NOT NULL DEFAULT 0,
  "area" TEXT
);

CREATE TABLE IF NOT EXISTS "combos" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" TEXT NOT NULL,
  "description" TEXT,
  "price_cents" BIGINT NOT NULL,
  "slots" TEXT NOT NULL,
  "active" BIGINT NOT NULL DEFAULT 1,
  "online" BIGINT NOT NULL DEFAULT 1,
  "sort" BIGINT NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS "contests" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" TEXT NOT NULL,
  "metric" TEXT NOT NULL CHECK (metric IN ('items','sales','avg_ticket','orders')),
  "item_ids" TEXT NOT NULL DEFAULT '[]',
  "categories" TEXT NOT NULL DEFAULT '[]',
  "starts" TEXT NOT NULL,
  "ends" TEXT NOT NULL,
  "prize" TEXT,
  "active" BIGINT NOT NULL DEFAULT 1,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "customers" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" TEXT NOT NULL,
  "email" TEXT NOT NULL UNIQUE,
  "phone" TEXT,
  "pw_hash" TEXT NOT NULL,
  "session_version" BIGINT NOT NULL DEFAULT 1,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "last_login_at" TEXT,
  "visits" BIGINT NOT NULL DEFAULT 0,
  "marketing_opt_in" BIGINT NOT NULL DEFAULT 0,
  "birthday" TEXT,
  "notes" TEXT,
  "tags" TEXT NOT NULL DEFAULT '[]',
  "card_token" TEXT,
  "ref_code" TEXT,
  "referred_by" BIGINT,
  "referral_rewarded" BIGINT NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS "delivery_photos" (
  "order_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "data" TEXT NOT NULL,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "delivery_signatures" (
  "order_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "data" TEXT NOT NULL,
  "name" TEXT,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "delivery_zones" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" TEXT NOT NULL,
  "points" TEXT NOT NULL,
  "fee_cents" BIGINT NOT NULL DEFAULT 0,
  "min_cents" BIGINT NOT NULL DEFAULT 0,
  "color" TEXT,
  "active" BIGINT NOT NULL DEFAULT 1,
  "sort" BIGINT NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS "desk_alerts" (
  "key" TEXT PRIMARY KEY,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "devices" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "device_id" TEXT NOT NULL UNIQUE,
  "name" TEXT,
  "user_agent" TEXT,
  "ip" TEXT,
  "status" TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','blocked')),
  "code" TEXT,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "last_seen" TEXT,
  "approved_by" BIGINT
);

CREATE TABLE IF NOT EXISTS "dish_ratings" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "feedback_id" BIGINT NOT NULL,
  "item_id" BIGINT,
  "name" TEXT NOT NULL,
  "liked" BIGINT NOT NULL,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  UNIQUE (feedback_id, name)
);

CREATE TABLE IF NOT EXISTS "driver_pos" (
  "user_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "lat" DOUBLE PRECISION NOT NULL,
  "lng" DOUBLE PRECISION NOT NULL,
  "at" TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS "equipment" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" TEXT NOT NULL,
  "location" TEXT,
  "make_model" TEXT,
  "serial" TEXT,
  "vendor" TEXT,
  "vendor_phone" TEXT,
  "warranty_until" TEXT,
  "service_every_days" BIGINT,
  "last_service" TEXT,
  "notes" TEXT,
  "active" BIGINT NOT NULL DEFAULT 1
);

CREATE TABLE IF NOT EXISTS "equipment_events" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "equipment_id" BIGINT NOT NULL,
  "kind" TEXT NOT NULL CHECK (kind IN ('service','repair','issue','note')),
  "notes" TEXT,
  "cost_cents" BIGINT NOT NULL DEFAULT 0,
  "status" TEXT NOT NULL DEFAULT 'done' CHECK (status IN ('open','done')),
  "user_id" BIGINT,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "events" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "title" TEXT NOT NULL,
  "description" TEXT,
  "starts_local" TEXT NOT NULL,
  "ends_local" TEXT,
  "capacity" BIGINT NOT NULL,
  "price_cents" BIGINT NOT NULL DEFAULT 0,
  "max_per_order" BIGINT NOT NULL DEFAULT 6,
  "active" BIGINT NOT NULL DEFAULT 1,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "feedback" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "guest_id" BIGINT NOT NULL UNIQUE,
  "customer_id" BIGINT,
  "token" TEXT NOT NULL UNIQUE,
  "send_after" TEXT NOT NULL,
  "sent_at" TEXT,
  "rating" BIGINT,
  "comment" TEXT,
  "responded_at" TEXT,
  "review_clicked" BIGINT NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS "fire_reminders" (
  "key" TEXT PRIMARY KEY,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "gift_cards" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "code" TEXT NOT NULL UNIQUE,
  "initial_cents" BIGINT NOT NULL,
  "balance_cents" BIGINT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','disabled')),
  "name" TEXT,
  "email" TEXT,
  "source" TEXT NOT NULL DEFAULT 'staff',
  "created_by" BIGINT,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "wallet_token" TEXT,
  "valid_from" TEXT,
  "valid_until" TEXT
);

CREATE TABLE IF NOT EXISTS "gift_promos" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" TEXT NOT NULL,
  "min_cents" BIGINT NOT NULL,
  "bonus_cents" BIGINT NOT NULL,
  "starts" TEXT NOT NULL,
  "ends" TEXT NOT NULL,
  "bonus_from" TEXT,
  "bonus_until" TEXT,
  "active" BIGINT NOT NULL DEFAULT 1
);

CREATE TABLE IF NOT EXISTS "gift_txns" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "card_id" BIGINT NOT NULL,
  "delta_cents" BIGINT NOT NULL,
  "order_id" BIGINT,
  "method" TEXT,
  "user_id" BIGINT,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "guests" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "kind" TEXT NOT NULL DEFAULT 'table' CHECK (kind IN ('table','order')),
  "name" TEXT NOT NULL,
  "phone" TEXT,
  "party_size" BIGINT NOT NULL DEFAULT 2,
  "notes" TEXT,
  "status" TEXT NOT NULL DEFAULT 'waiting' CHECK (status IN ('waiting','buzzed','acknowledged','seated','done','cancelled','noshow')),
  "token" TEXT NOT NULL UNIQUE,
  "source" TEXT NOT NULL DEFAULT 'staff',
  "buzz_count" BIGINT NOT NULL DEFAULT 0,
  "last_message" TEXT,
  "table_id" BIGINT,
  "order_id" BIGINT,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "buzzed_at" TEXT,
  "acknowledged_at" TEXT,
  "seated_at" TEXT,
  "closed_at" TEXT,
  "email" TEXT,
  "notify_email" BIGINT NOT NULL DEFAULT 0,
  "heads_up_at" TEXT,
  "preorder_open" BIGINT NOT NULL DEFAULT 0,
  "customer_id" BIGINT,
  "booking_id" BIGINT,
  "ahead_at_join" BIGINT,
  "vip_alerted" BIGINT NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS "handoff_notes" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" BIGINT NOT NULL,
  "body" TEXT NOT NULL,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "house_alerts" (
  "key" TEXT PRIMARY KEY,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "ingredient_86" (
  "item_id" BIGINT NOT NULL,
  "ingredient_id" BIGINT NOT NULL,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY (item_id, ingredient_id)
);

CREATE TABLE IF NOT EXISTS "ingredient_costs" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ingredient_id" BIGINT NOT NULL,
  "old_cents" DOUBLE PRECISION,
  "new_cents" DOUBLE PRECISION NOT NULL,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "alerted" BIGINT NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS "ingredient_lots" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ingredient_id" BIGINT NOT NULL,
  "qty" DOUBLE PRECISION NOT NULL,
  "received_on" TEXT NOT NULL,
  "use_by" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','used','tossed')),
  "source" TEXT,
  "alerted" TEXT,
  "closed_at" TEXT
);

CREATE TABLE IF NOT EXISTS "ingredient_moves" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ingredient_id" BIGINT NOT NULL,
  "delta" DOUBLE PRECISION NOT NULL,
  "reason" TEXT,
  "order_id" BIGINT,
  "user_id" BIGINT,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "ingredient_prices" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ingredient_id" BIGINT NOT NULL,
  "supplier_id" BIGINT NOT NULL,
  "cost_cents" DOUBLE PRECISION NOT NULL,
  "source" TEXT NOT NULL DEFAULT 'quote',
  "note" TEXT,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  UNIQUE (ingredient_id, supplier_id)
);

CREATE TABLE IF NOT EXISTS "ingredients" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" TEXT NOT NULL,
  "unit" TEXT NOT NULL DEFAULT 'each',
  "cost_cents" DOUBLE PRECISION NOT NULL DEFAULT 0,
  "stock" DOUBLE PRECISION,
  "low" DOUBLE PRECISION NOT NULL DEFAULT 0,
  "par" DOUBLE PRECISION,
  "supplier_id" BIGINT,
  "low_alerted" BIGINT NOT NULL DEFAULT 0,
  "active" BIGINT NOT NULL DEFAULT 1,
  "kcal" DOUBLE PRECISION,
  "barcode" TEXT,
  "shelf_days" BIGINT,
  "manual_out" BIGINT NOT NULL DEFAULT 0,
  "prev_stock" DOUBLE PRECISION
);

CREATE TABLE IF NOT EXISTS "insight_alerts" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "kind" TEXT NOT NULL,
  "key" TEXT NOT NULL UNIQUE,
  "title" TEXT NOT NULL,
  "body" TEXT NOT NULL,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "insights" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "day" TEXT NOT NULL UNIQUE,
  "data" TEXT NOT NULL,
  "sent_at" TEXT
);

CREATE TABLE IF NOT EXISTS "invoice_payments" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "invoice_id" BIGINT NOT NULL,
  "amount_cents" BIGINT NOT NULL,
  "method" TEXT NOT NULL,
  "note" TEXT,
  "payment_id" BIGINT,
  "user_id" BIGINT,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "invoices" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "token" TEXT NOT NULL UNIQUE,
  "title" TEXT NOT NULL,
  "customer_name" TEXT NOT NULL,
  "email" TEXT,
  "phone" TEXT,
  "event_date" TEXT,
  "event_notes" TEXT,
  "lines" TEXT NOT NULL DEFAULT '[]',
  "tax_rate" DOUBLE PRECISION NOT NULL DEFAULT 0,
  "deposit_pct" DOUBLE PRECISION NOT NULL DEFAULT 0,
  "fee_cents" BIGINT NOT NULL DEFAULT 0,
  "status" TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','sent','accepted','deposit_paid','paid','cancelled')),
  "accepted_name" TEXT,
  "created_by" BIGINT,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "sent_at" TEXT,
  "accepted_at" TEXT,
  "paid_at" TEXT,
  "due_date" TEXT,
  "source" TEXT NOT NULL DEFAULT 'staff'
);

CREATE TABLE IF NOT EXISTS "item_mod_groups" (
  "item_id" BIGINT NOT NULL,
  "group_id" BIGINT NOT NULL,
  PRIMARY KEY (item_id, group_id)
);

CREATE TABLE IF NOT EXISTS "item_recipes" (
  "item_id" BIGINT NOT NULL,
  "ingredient_id" BIGINT NOT NULL,
  "qty" DOUBLE PRECISION NOT NULL,
  PRIMARY KEY (item_id, ingredient_id)
);

CREATE TABLE IF NOT EXISTS "kds_messages" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "from_area" TEXT NOT NULL,
  "to_area" TEXT NOT NULL,
  "body" TEXT NOT NULL,
  "by_label" TEXT,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "ack_at" TEXT,
  "ack_by" TEXT
);

CREATE TABLE IF NOT EXISTS "kds_timers" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "area" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "minutes" DOUBLE PRECISION NOT NULL,
  "repeat" BIGINT NOT NULL DEFAULT 1,
  "due_at" TEXT,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "labor_alerts" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "key" TEXT NOT NULL UNIQUE,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "link_hits" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "src" TEXT NOT NULL,
  "target" TEXT NOT NULL,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "locations" (
  "slug" TEXT PRIMARY KEY,
  "name" TEXT NOT NULL,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "log_entries" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "day" TEXT NOT NULL,
  "kind" TEXT NOT NULL DEFAULT 'note',
  "body" TEXT NOT NULL,
  "must_read" BIGINT NOT NULL DEFAULT 0,
  "audience" TEXT NOT NULL DEFAULT 'managers',
  "user_id" BIGINT,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "log_reads" (
  "entry_id" BIGINT NOT NULL,
  "user_id" BIGINT NOT NULL,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY (entry_id, user_id)
);

CREATE TABLE IF NOT EXISTS "membership_plans" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" TEXT NOT NULL,
  "description" TEXT,
  "price_cents" BIGINT NOT NULL,
  "period" TEXT NOT NULL DEFAULT 'month' CHECK (period IN ('month','year')),
  "discount_pct" DOUBLE PRECISION NOT NULL DEFAULT 0,
  "perk_name" TEXT,
  "perk_qty" BIGINT NOT NULL DEFAULT 0,
  "active" BIGINT NOT NULL DEFAULT 1,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "memberships" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "customer_id" BIGINT NOT NULL,
  "plan_id" BIGINT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','active','past_due','cancelled')),
  "current_until" TEXT,
  "perks_used" BIGINT NOT NULL DEFAULT 0,
  "cancel_at_end" BIGINT NOT NULL DEFAULT 0,
  "renewal_payment_id" BIGINT,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "started_at" TEXT
);

CREATE TABLE IF NOT EXISTS "menu_items" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" TEXT NOT NULL,
  "category" TEXT NOT NULL DEFAULT 'General',
  "price_cents" BIGINT NOT NULL,
  "color" TEXT NOT NULL DEFAULT '#7c5cff',
  "active" BIGINT NOT NULL DEFAULT 1,
  "sort" BIGINT NOT NULL DEFAULT 0,
  "guest_orderable" BIGINT NOT NULL DEFAULT 0,
  "stock" BIGINT,
  "low_stock" BIGINT NOT NULL DEFAULT 5,
  "description" TEXT,
  "allergens" TEXT NOT NULL DEFAULT '[]',
  "diet" TEXT NOT NULL DEFAULT '[]',
  "i18n" TEXT NOT NULL DEFAULT '{}',
  "special_only" BIGINT NOT NULL DEFAULT 0,
  "build_steps" TEXT NOT NULL DEFAULT '[]',
  "photo_version" TEXT NOT NULL DEFAULT '0',
  "shelf_days" BIGINT,
  "calories" BIGINT,
  "cook_minutes" BIGINT,
  "show_photo" BIGINT NOT NULL DEFAULT 1,
  "station" TEXT,
  "prep_par" BIGINT
);

CREATE TABLE IF NOT EXISTS "menu_schedules" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" TEXT NOT NULL,
  "days" TEXT NOT NULL DEFAULT '[0,1,2,3,4,5,6]',
  "start_time" TEXT NOT NULL,
  "end_time" TEXT NOT NULL,
  "item_ids" TEXT NOT NULL DEFAULT '[]',
  "categories" TEXT NOT NULL DEFAULT '[]',
  "active" BIGINT NOT NULL DEFAULT 1
);

CREATE TABLE IF NOT EXISTS "messages" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "guest_id" BIGINT NOT NULL,
  "sender" TEXT NOT NULL CHECK (sender IN ('guest','staff')),
  "user_id" BIGINT,
  "body" TEXT NOT NULL,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "read_at" TEXT
);

CREATE TABLE IF NOT EXISTS "mod_groups" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" TEXT NOT NULL,
  "min_pick" BIGINT NOT NULL DEFAULT 0,
  "max_pick" BIGINT NOT NULL DEFAULT 1,
  "sort" BIGINT NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS "mod_options" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "group_id" BIGINT NOT NULL,
  "name" TEXT NOT NULL,
  "price_cents" BIGINT NOT NULL DEFAULT 0,
  "sort" BIGINT NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS "order_items" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "order_id" BIGINT NOT NULL,
  "item_id" BIGINT,
  "name" TEXT NOT NULL,
  "qty" BIGINT NOT NULL,
  "price_cents" BIGINT NOT NULL,
  "note" TEXT,
  "mods" TEXT,
  "course" BIGINT NOT NULL DEFAULT 1,
  "fired_at" TEXT,
  "done_at" TEXT,
  "done_station" TEXT,
  "seat" BIGINT,
  "done_by" BIGINT,
  "seat_name" TEXT
);

CREATE TABLE IF NOT EXISTS "orders" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "number" BIGINT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('held','open','sent','ready','paid','void')),
  "table_id" BIGINT,
  "guest_id" BIGINT,
  "customer_name" TEXT,
  "subtotal_cents" BIGINT NOT NULL DEFAULT 0,
  "tax_cents" BIGINT NOT NULL DEFAULT 0,
  "tip_cents" BIGINT NOT NULL DEFAULT 0,
  "discount_cents" BIGINT NOT NULL DEFAULT 0,
  "total_cents" BIGINT NOT NULL DEFAULT 0,
  "payment_method" TEXT,
  "created_by" BIGINT,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "sent_at" TEXT,
  "ready_at" TEXT,
  "paid_at" TEXT,
  "source" TEXT NOT NULL DEFAULT 'staff',
  "fee_cents" BIGINT NOT NULL DEFAULT 0,
  "gift_cents" BIGINT NOT NULL DEFAULT 0,
  "promo_code" TEXT,
  "fulfillment" TEXT NOT NULL DEFAULT 'dine_in',
  "delivery_address" TEXT,
  "contact_phone" TEXT,
  "contact_email" TEXT,
  "client_key" TEXT,
  "prepaid" BIGINT NOT NULL DEFAULT 0,
  "order_notes" TEXT,
  "receipt_token" TEXT,
  "driver_id" BIGINT,
  "out_at" TEXT,
  "delivered_at" TEXT,
  "drop_lat" DOUBLE PRECISION,
  "drop_lng" DOUBLE PRECISION,
  "customer_id" BIGINT,
  "allergy_note" TEXT,
  "table_alerted" BIGINT NOT NULL DEFAULT 0,
  "scheduled_for" TEXT,
  "sched_pay" TEXT,
  "packed_at" TEXT,
  "expo_at" TEXT,
  "allergy_checked_by" TEXT,
  "arrived_at" TEXT,
  "arrival_note" TEXT,
  "handed_at" TEXT,
  "pass_alerted" TEXT,
  "promised_at" TEXT,
  "shelf" TEXT,
  "eta_minutes" BIGINT,
  "eta_km" DOUBLE PRECISION,
  "eta_at" TEXT,
  "served_at" TEXT,
  "makegood_at" TEXT,
  "makegood_alerted" TEXT,
  "tab_id" BIGINT,
  "tab_member" TEXT,
  "priority" BIGINT NOT NULL DEFAULT 0,
  "vip_checked" BIGINT NOT NULL DEFAULT 0,
  "allergy_handed_by" TEXT,
  "allergy_handed_at" TEXT
);

CREATE TABLE IF NOT EXISTS "owner_alerts" (
  "key" TEXT PRIMARY KEY,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "payments" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "kind" TEXT NOT NULL DEFAULT 'bill',
  "bill_id" BIGINT,
  "amount_cents" BIGINT NOT NULL,
  "tip_cents" BIGINT NOT NULL DEFAULT 0,
  "method" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'pending',
  "label" TEXT,
  "items" TEXT,
  "meta" TEXT,
  "stripe_session" TEXT,
  "user_id" BIGINT,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "paid_at" TEXT,
  "pay_token" TEXT,
  "success_url" TEXT,
  "cancel_url" TEXT,
  "descr" TEXT,
  "lines_json" TEXT,
  "email" TEXT,
  "provider" TEXT,
  "provider_ref" TEXT,
  "refund_ref" TEXT,
  "claim_app" TEXT,
  "claim_name" TEXT,
  "claimed_at" TEXT,
  "bank_status" TEXT
);

CREATE TABLE IF NOT EXISTS "plate_photos" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "order_id" BIGINT NOT NULL,
  "data" TEXT NOT NULL,
  "by_label" TEXT,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "plus_alerts" (
  "key" TEXT PRIMARY KEY,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "po_lines" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "po_id" BIGINT NOT NULL,
  "ingredient_id" BIGINT NOT NULL,
  "qty" DOUBLE PRECISION NOT NULL,
  "cost_cents" DOUBLE PRECISION NOT NULL DEFAULT 0,
  "received_qty" DOUBLE PRECISION
);

CREATE TABLE IF NOT EXISTS "prep_counts" (
  "date" TEXT NOT NULL,
  "item_id" BIGINT NOT NULL,
  "qty" BIGINT NOT NULL,
  "by_label" TEXT,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY (date, item_id)
);

CREATE TABLE IF NOT EXISTS "prep_leftovers" (
  "date" TEXT NOT NULL,
  "item_id" BIGINT NOT NULL,
  "qty" BIGINT NOT NULL,
  "by_label" TEXT,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY (date, item_id)
);

CREATE TABLE IF NOT EXISTS "prep_log" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "day" TEXT NOT NULL,
  "area" TEXT NOT NULL,
  "kind" TEXT NOT NULL,
  "ref_id" BIGINT NOT NULL,
  "name" TEXT NOT NULL,
  "qty" DOUBLE PRECISION NOT NULL,
  "by_label" TEXT,
  "lot_id" BIGINT,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  UNIQUE (day, area, kind, ref_id)
);

CREATE TABLE IF NOT EXISTS "price_rules" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" TEXT NOT NULL,
  "days" TEXT NOT NULL DEFAULT '[0,1,2,3,4,5,6]',
  "start_time" TEXT NOT NULL,
  "end_time" TEXT NOT NULL,
  "kind" TEXT NOT NULL CHECK (kind IN ('pct','amount','price')),
  "value" BIGINT NOT NULL,
  "item_ids" TEXT NOT NULL DEFAULT '[]',
  "categories" TEXT NOT NULL DEFAULT '[]',
  "channels" TEXT NOT NULL DEFAULT 'all',
  "active" BIGINT NOT NULL DEFAULT 1
);

CREATE TABLE IF NOT EXISTS "print_agents" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" TEXT NOT NULL,
  "kind" TEXT NOT NULL DEFAULT 'browser',
  "last_seen" TEXT,
  "info" TEXT,
  "active" BIGINT NOT NULL DEFAULT 1,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "print_jobs" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "printer_id" BIGINT NOT NULL,
  "kind" TEXT NOT NULL,
  "title" TEXT,
  "payload" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'queued',
  "tries" BIGINT NOT NULL DEFAULT 0,
  "error" TEXT,
  "by_label" TEXT,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "sent_at" TEXT,
  "done_at" TEXT
);

CREATE TABLE IF NOT EXISTS "printers" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" TEXT NOT NULL,
  "agent_id" BIGINT,
  "connection" TEXT NOT NULL DEFAULT 'network',
  "address" TEXT,
  "width" BIGINT NOT NULL DEFAULT 42,
  "jobs" TEXT NOT NULL DEFAULT '[]',
  "area" TEXT,
  "copies" BIGINT NOT NULL DEFAULT 1,
  "cut" BIGINT NOT NULL DEFAULT 1,
  "drawer" BIGINT NOT NULL DEFAULT 0,
  "active" BIGINT NOT NULL DEFAULT 1,
  "last_ok" TEXT,
  "last_error" TEXT,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "backup_id" BIGINT
);

CREATE TABLE IF NOT EXISTS "promos" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "code" TEXT NOT NULL UNIQUE,
  "kind" TEXT NOT NULL CHECK (kind IN ('pct','amount')),
  "value" BIGINT NOT NULL,
  "min_cents" BIGINT NOT NULL DEFAULT 0,
  "starts_on" TEXT,
  "ends_on" TEXT,
  "max_uses" BIGINT,
  "active" BIGINT NOT NULL DEFAULT 1,
  "note" TEXT,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "punch_cards" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "customer_id" BIGINT NOT NULL,
  "plan_id" BIGINT NOT NULL,
  "uses_left" BIGINT NOT NULL,
  "expires_on" TEXT NOT NULL,
  "payment_id" BIGINT,
  "order_id" BIGINT,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "punch_photos" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" BIGINT NOT NULL,
  "action" TEXT NOT NULL,
  "data" TEXT NOT NULL,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "punch_plans" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" TEXT NOT NULL,
  "uses" BIGINT NOT NULL,
  "price_cents" BIGINT NOT NULL,
  "item_ids" TEXT NOT NULL DEFAULT '[]',
  "categories" TEXT NOT NULL DEFAULT '[]',
  "valid_days" BIGINT NOT NULL DEFAULT 365,
  "online" BIGINT NOT NULL DEFAULT 1,
  "active" BIGINT NOT NULL DEFAULT 1
);

CREATE TABLE IF NOT EXISTS "punch_uses" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "card_id" BIGINT NOT NULL,
  "order_id" BIGINT NOT NULL,
  "item_name" TEXT NOT NULL,
  "cents" BIGINT NOT NULL,
  "user_id" BIGINT,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "purchase_orders" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "supplier_id" BIGINT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','sent','received','cancelled')),
  "notes" TEXT,
  "created_by" BIGINT,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "sent_at" TEXT,
  "received_at" TEXT,
  "auto" BIGINT NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS "push_subs" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "guest_id" BIGINT,
  "customer_id" BIGINT,
  "endpoint" TEXT NOT NULL UNIQUE,
  "p256dh" TEXT NOT NULL,
  "auth" TEXT NOT NULL,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "user_id" BIGINT
);

CREATE TABLE IF NOT EXISTS "recoveries" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "feedback_id" BIGINT NOT NULL UNIQUE,
  "code" TEXT NOT NULL,
  "reached" BIGINT NOT NULL DEFAULT 0,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "recovery_codes" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" BIGINT NOT NULL,
  "code_hash" TEXT NOT NULL,
  "used_at" TEXT
);

CREATE TABLE IF NOT EXISTS "refunds" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "order_id" BIGINT NOT NULL,
  "amount_cents" BIGINT NOT NULL,
  "reason" TEXT,
  "method" TEXT,
  "user_id" BIGINT,
  "approved_by" BIGINT,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "remake_alerts" (
  "key" TEXT PRIMARY KEY,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "remakes" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "order_id" BIGINT NOT NULL,
  "order_item_id" BIGINT,
  "item_id" BIGINT,
  "name" TEXT NOT NULL,
  "qty" BIGINT NOT NULL DEFAULT 1,
  "reason" TEXT NOT NULL,
  "area" TEXT,
  "cost_cents" BIGINT NOT NULL DEFAULT 0,
  "by_label" TEXT,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "rewards" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "customer_id" BIGINT NOT NULL,
  "title" TEXT NOT NULL,
  "code" TEXT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','redeemed','expired')),
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "redeemed_at" TEXT,
  "redeemed_by" BIGINT
);

CREATE TABLE IF NOT EXISTS "room_bookings" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "room_id" BIGINT NOT NULL,
  "token" TEXT NOT NULL UNIQUE,
  "name" TEXT NOT NULL,
  "email" TEXT,
  "phone" TEXT,
  "date" TEXT NOT NULL,
  "start_time" TEXT NOT NULL,
  "end_time" TEXT NOT NULL,
  "guests" BIGINT NOT NULL,
  "occasion" TEXT,
  "notes" TEXT,
  "status" TEXT NOT NULL DEFAULT 'requested' CHECK (status IN ('requested','confirmed','declined','cancelled','done')),
  "min_spend_cents" BIGINT NOT NULL DEFAULT 0,
  "fee_cents" BIGINT NOT NULL DEFAULT 0,
  "deposit_cents" BIGINT NOT NULL DEFAULT 0,
  "deposit_paid_cents" BIGINT NOT NULL DEFAULT 0,
  "credit_code" TEXT,
  "source" TEXT NOT NULL DEFAULT 'online',
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "menu" TEXT NOT NULL DEFAULT '[]',
  "fire_time" TEXT,
  "fired_order_id" BIGINT
);

CREATE TABLE IF NOT EXISTS "rooms" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" TEXT NOT NULL,
  "capacity" BIGINT NOT NULL DEFAULT 20,
  "min_spend_cents" BIGINT NOT NULL DEFAULT 0,
  "deposit_pct" DOUBLE PRECISION NOT NULL DEFAULT 0,
  "fee_cents" BIGINT NOT NULL DEFAULT 0,
  "table_ids" TEXT NOT NULL DEFAULT '[]',
  "description" TEXT,
  "active" BIGINT NOT NULL DEFAULT 1
);

CREATE TABLE IF NOT EXISTS "safe_log" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "kind" TEXT NOT NULL CHECK (kind IN ('count','drop','to_bank','adjust')),
  "amount_cents" BIGINT NOT NULL,
  "expected_cents" BIGINT,
  "note" TEXT,
  "user_id" BIGINT NOT NULL,
  "witness_id" BIGINT,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "schedule" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" BIGINT NOT NULL,
  "start_local" TEXT NOT NULL,
  "end_local" TEXT NOT NULL,
  "role_note" TEXT
);

CREATE TABLE IF NOT EXISTS "seat_allergies" (
  "table_id" BIGINT NOT NULL,
  "seat" BIGINT NOT NULL,
  "allergy" TEXT NOT NULL,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "name" TEXT,
  PRIMARY KEY (table_id, seat)
);

CREATE TABLE IF NOT EXISTS "settings" (
  "key" TEXT PRIMARY KEY,
  "value" TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS "shift_pulse" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" BIGINT NOT NULL,
  "shift_id" BIGINT,
  "rating" BIGINT NOT NULL,
  "note" TEXT,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "shift_swaps" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "schedule_id" BIGINT NOT NULL,
  "from_user" BIGINT NOT NULL,
  "to_user" BIGINT,
  "claimed_by" BIGINT,
  "note" TEXT,
  "status" TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','claimed','approved','denied','cancelled')),
  "decided_by" BIGINT,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "shifts" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" BIGINT NOT NULL,
  "clock_in" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "clock_out" TEXT,
  "break_minutes" BIGINT NOT NULL DEFAULT 0,
  "edited_by" BIGINT,
  "break_started" TEXT,
  "source" TEXT NOT NULL DEFAULT 'lock',
  "declared_tips_cents" BIGINT NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS "specials" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "item_id" BIGINT NOT NULL,
  "day" TEXT,
  "dow" BIGINT,
  "price_cents" BIGINT,
  "note" TEXT,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "stock_moves" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "item_id" BIGINT NOT NULL,
  "delta" BIGINT NOT NULL,
  "reason" TEXT,
  "user_id" BIGINT,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "stock_transfers" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "direction" TEXT NOT NULL CHECK (direction IN ('out','in')),
  "other_slug" TEXT NOT NULL,
  "other_name" TEXT,
  "lines" TEXT NOT NULL,
  "note" TEXT,
  "user_name" TEXT,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "supplier_bills" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "supplier_id" BIGINT NOT NULL,
  "po_id" BIGINT,
  "number" TEXT,
  "bill_date" TEXT NOT NULL,
  "due_date" TEXT NOT NULL,
  "amount_cents" BIGINT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','paid','void')),
  "category" TEXT NOT NULL DEFAULT 'food',
  "note" TEXT,
  "photo_version" TEXT NOT NULL DEFAULT '0',
  "created_by" BIGINT,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "paid_at" TEXT
);

CREATE TABLE IF NOT EXISTS "supplier_credits" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "supplier_id" BIGINT NOT NULL,
  "po_id" BIGINT,
  "amount_cents" BIGINT NOT NULL,
  "reason" TEXT NOT NULL,
  "items" TEXT,
  "status" TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','applied','void')),
  "bill_id" BIGINT,
  "created_by" BIGINT,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "applied_at" TEXT
);

CREATE TABLE IF NOT EXISTS "suppliers" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" TEXT NOT NULL,
  "email" TEXT,
  "phone" TEXT,
  "notes" TEXT,
  "active" BIGINT NOT NULL DEFAULT 1,
  "terms_days" BIGINT NOT NULL DEFAULT 30
);

CREATE TABLE IF NOT EXISTS "table_calls" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "table_id" BIGINT NOT NULL,
  "kind" TEXT NOT NULL,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "ack_at" TEXT,
  "ack_by" BIGINT
);

CREATE TABLE IF NOT EXISTS "table_combos" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" TEXT NOT NULL,
  "table_ids" TEXT NOT NULL,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "tables" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "label" TEXT NOT NULL,
  "seats" BIGINT NOT NULL DEFAULT 4,
  "zone" TEXT NOT NULL DEFAULT 'Main',
  "status" TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','reserved','seated','dirty')),
  "guest_id" BIGINT,
  "seated_at" TEXT,
  "x" DOUBLE PRECISION,
  "y" DOUBLE PRECISION,
  "w" DOUBLE PRECISION,
  "h" DOUBLE PRECISION,
  "shape" TEXT NOT NULL DEFAULT 'square',
  "server_id" BIGINT,
  "qr_token" TEXT,
  "joined_to" BIGINT
);

CREATE TABLE IF NOT EXISTS "tabs" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "token" TEXT NOT NULL UNIQUE,
  "table_id" BIGINT,
  "name" TEXT NOT NULL,
  "phone" TEXT,
  "status" TEXT NOT NULL DEFAULT 'open',
  "bill_id" BIGINT,
  "opened_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "closed_at" TEXT,
  "code" TEXT
);

CREATE TABLE IF NOT EXISTS "temp_logs" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "unit_id" BIGINT NOT NULL,
  "value" DOUBLE PRECISION NOT NULL,
  "ok" BIGINT NOT NULL,
  "note" TEXT,
  "corrective" TEXT,
  "user_id" BIGINT,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "temp_units" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" TEXT NOT NULL,
  "min_temp" DOUBLE PRECISION NOT NULL,
  "max_temp" DOUBLE PRECISION NOT NULL,
  "scale" TEXT NOT NULL DEFAULT 'F',
  "active" BIGINT NOT NULL DEFAULT 1,
  "area" TEXT
);

CREATE TABLE IF NOT EXISTS "terminal_charges" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "bill_id" BIGINT NOT NULL,
  "reader_id" TEXT NOT NULL,
  "pi_id" TEXT NOT NULL UNIQUE,
  "amount_cents" BIGINT NOT NULL,
  "tip_cents" BIGINT NOT NULL DEFAULT 0,
  "share" TEXT,
  "status" TEXT NOT NULL DEFAULT 'waiting',
  "error" TEXT,
  "user_id" BIGINT,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "done_at" TEXT
);

CREATE TABLE IF NOT EXISTS "tickets" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "event_id" BIGINT NOT NULL,
  "code" TEXT NOT NULL UNIQUE,
  "name" TEXT NOT NULL,
  "email" TEXT,
  "phone" TEXT,
  "qty" BIGINT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','paid','checked_in','cancelled')),
  "payment_id" BIGINT,
  "checked_in" BIGINT NOT NULL DEFAULT 0,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "checked_in_at" TEXT
);

CREATE TABLE IF NOT EXISTS "time_off" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" BIGINT NOT NULL,
  "start_date" TEXT NOT NULL,
  "end_date" TEXT NOT NULL,
  "reason" TEXT,
  "status" TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','denied','cancelled')),
  "decided_by" BIGINT,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "tip_payouts" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "period_from" TEXT NOT NULL,
  "period_to" TEXT NOT NULL,
  "user_id" BIGINT NOT NULL,
  "hours" DOUBLE PRECISION NOT NULL,
  "points" DOUBLE PRECISION NOT NULL,
  "cents" BIGINT NOT NULL,
  "method" TEXT NOT NULL DEFAULT 'payroll',
  "paid_by" BIGINT,
  "paid_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "training_modules" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "title" TEXT NOT NULL,
  "body" TEXT NOT NULL DEFAULT '',
  "roles" TEXT NOT NULL DEFAULT '["staff","manager"]',
  "item_id" BIGINT,
  "required" BIGINT NOT NULL DEFAULT 1,
  "active" BIGINT NOT NULL DEFAULT 1,
  "sort" BIGINT NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS "training_progress" (
  "user_id" BIGINT NOT NULL,
  "module_id" BIGINT NOT NULL,
  "read_at" TEXT,
  "signed_by" BIGINT,
  "signed_at" TEXT,
  PRIMARY KEY (user_id, module_id)
);

CREATE TABLE IF NOT EXISTS "users" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" TEXT NOT NULL,
  "role" TEXT NOT NULL CHECK (role IN ('owner','manager','staff')),
  "pin_hash" TEXT NOT NULL,
  "session_version" BIGINT NOT NULL DEFAULT 1,
  "active" BIGINT NOT NULL DEFAULT 1,
  "last_login_at" TEXT,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "hub_key" TEXT,
  "hourly_cents" BIGINT NOT NULL DEFAULT 0,
  "totp_secret" TEXT,
  "totp_enabled" BIGINT NOT NULL DEFAULT 0,
  "totp_last_step" BIGINT NOT NULL DEFAULT 0,
  "tip_points" DOUBLE PRECISION NOT NULL DEFAULT 1,
  "is_driver" BIGINT NOT NULL DEFAULT 0,
  "tip_role" TEXT NOT NULL DEFAULT '',
  "payroll_id" TEXT,
  "area" TEXT
);

CREATE TABLE IF NOT EXISTS "waste_log" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "item_id" BIGINT,
  "ingredient_id" BIGINT,
  "name" TEXT NOT NULL,
  "qty" DOUBLE PRECISION NOT NULL,
  "unit" TEXT,
  "reason" TEXT NOT NULL,
  "cost_cents" BIGINT NOT NULL,
  "note" TEXT,
  "user_id" BIGINT,
  "at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE INDEX IF NOT EXISTS idx_guests_status ON guests(status);
CREATE INDEX IF NOT EXISTS idx_push_guest ON push_subs(guest_id);
CREATE INDEX IF NOT EXISTS idx_bookings_start ON bookings(start_local);
CREATE INDEX IF NOT EXISTS idx_bookings_customer ON bookings(customer_id);
CREATE INDEX IF NOT EXISTS idx_shifts_user ON shifts(user_id, clock_in);
CREATE UNIQUE INDEX IF NOT EXISTS idx_orders_client_key ON orders(client_key);
CREATE UNIQUE INDEX IF NOT EXISTS idx_tables_qr ON tables(qr_token);
CREATE INDEX IF NOT EXISTS idx_payments_bill ON payments(bill_id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_orders_receipt ON orders(receipt_token);
CREATE INDEX IF NOT EXISTS idx_auto_sends ON auto_sends(customer_id, flow);
CREATE INDEX IF NOT EXISTS idx_ing_moves ON ingredient_moves(ingredient_id, at);
CREATE UNIQUE INDEX IF NOT EXISTS idx_payments_token ON payments(pay_token);
CREATE INDEX IF NOT EXISTS idx_members_customer ON memberships(customer_id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_customers_card ON customers(card_token);
CREATE INDEX IF NOT EXISTS idx_link_hits ON link_hits(at);
CREATE INDEX IF NOT EXISTS idx_messages_guest ON messages(guest_id, id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_customers_ref ON customers(ref_code);
CREATE INDEX IF NOT EXISTS idx_temp_logs ON temp_logs(unit_id, at);
CREATE INDEX IF NOT EXISTS idx_tickets_event ON tickets(event_id);
CREATE INDEX IF NOT EXISTS idx_ingredient_costs ON ingredient_costs(ingredient_id, id);
CREATE INDEX IF NOT EXISTS idx_punch_photos_at ON punch_photos(at);
CREATE INDEX IF NOT EXISTS idx_lots_open ON ingredient_lots(status, use_by);
CREATE INDEX IF NOT EXISTS idx_room_bookings_date ON room_bookings(date);
CREATE INDEX IF NOT EXISTS idx_print_jobs_status ON print_jobs(status, printer_id);
